const stock = 3;

const label = stock > 0 ? '있음' : '없음';

function getLabel() {
  return label;
}

function stockLabel(stock) {
  if (stock === 0) {
    return '품절';
  } else if (stock < 10) {
    return '재고 부족';
  } else {
    return '충분';
  }
}
